// ==========================================================
// utils/battle/tmData.js — read access to data/battle/tm-data.json
// (TM system phase T2; generated by tools/generate-tm-data.mjs).
//
// Pure data: which catalog moves exist (status "launch" or "hold"), their
// Gen 5 TM/HM number if any, and which species can learn each one by TM.
// Nothing here sells, teaches or prices a TM (later phases).
// ==========================================================

import fs from "fs";

const data = JSON.parse(fs.readFileSync(new URL("../../data/battle/tm-data.json", import.meta.url), "utf8"));
const learners = new Map(Object.entries(data.moves).map(([id, m]) => [id, new Set(m.species)]));
const own = (id) => (typeof id === "string" && Object.prototype.hasOwnProperty.call(data.moves, id) ? data.moves[id] : null);

export const TM_ITEM_PREFIX = "tm_";
export const tmItemId = (moveId) => `${TM_ITEM_PREFIX}${moveId}`;
/** "tm_thunderbolt" → "thunderbolt" when it names a catalog move, else null. */
export function moveIdForTmItem(itemId) {
  if (typeof itemId !== "string" || !itemId.startsWith(TM_ITEM_PREFIX)) return null;
  const id = itemId.slice(TM_ITEM_PREFIX.length);
  return own(id) ? id : null;
}

/** Catalog entry for a move: { status, tm, rule, introduced, holdReason? } or null. */
export function tmMove(moveId) {
  const m = own(moveId);
  if (!m) return null;
  const { species, ...rest } = m;
  return { id: moveId, ...rest };
}

/** Catalog move ids, optionally only one status ("launch" | "hold"). */
export function tmMoveIds({ status = null } = {}) {
  return Object.keys(data.moves).filter((id) => status == null || data.moves[id].status === status);
}

/** Can this species learn this catalog move by TM? (compatibility only, any status) */
export function canLearnByTm(speciesId, moveId) {
  return own(moveId) ? learners.get(moveId).has(Number(speciesId)) : false;
}

/** Catalog moves this species can learn by TM, optionally filtered by status. */
export function tmMovesForSpecies(speciesId, { status = null } = {}) {
  const n = Number(speciesId);
  return tmMoveIds({ status }).filter((id) => learners.get(id).has(n));
}

export const tmDataCounts = () => ({ ...data.counts });
